import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static int n, highest;
    static int[] bit; // Fenwick tree of 0/1 flags: is position i a strict prefix-minimum record?

    static void add(int i, int d) {
        for (; i <= n; i += i & -i) bit[i] += d;
    }

    static int prefix(int i) {
        int r = 0;
        for (; i > 0; i -= i & -i) r += bit[i];
        return r;
    }

    // Position of the k-th record (binary lifting on the Fenwick tree).
    static int kth(int k) {
        int index = 0;
        for (int step = highest; step > 0; step >>= 1)
            if (index + step <= n && bit[index + step] < k) {
                k -= bit[index + step];
                index += step;
            }
        return index + 1;
    }

    public static void main(String[] args) throws IOException {
        n = nextInt();
        int m = nextInt();
        long[] a = new long[n + 1];
        boolean[] active = new boolean[n + 1];
        bit = new int[n + 1];
        long smallest = Long.MAX_VALUE;
        int count = 0;
        for (int i = 1; i <= n; i++) {
            a[i] = nextLong();
            if (a[i] < smallest) {
                smallest = a[i];
                active[i] = true;
                count++;
            }
        }
        for (int i = 1; i <= n; i++) {
            if (active[i]) bit[i]++;
            int parent = i + (i & -i);
            if (parent <= n) bit[parent] += bit[i];
        }
        highest = Integer.highestOneBit(n);
        StringBuilder sb = new StringBuilder();
        for (int qi = 0; qi < m; qi++) {
            int pos = nextInt();
            a[pos] -= nextLong();
            int rank = prefix(pos);
            boolean changed = true;
            if (!active[pos]) {
                int previous = kth(rank); // nearest record to the left
                if (a[pos] >= a[previous]) changed = false;
                else {
                    add(pos, 1);
                    active[pos] = true;
                    count++;
                    rank++;
                }
            }
            // Later records that are no longer strictly smaller than a[pos] stop being records.
            while (changed && rank < count) {
                int following = kth(rank + 1);
                if (a[following] < a[pos]) break;
                add(following, -1);
                active[following] = false;
                count--;
            }
            if (qi > 0) sb.append(' ');
