package main

import (
	"io"
	"math"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

var n, highest int
var bit []int // Fenwick tree of 0/1 flags: is position i a strict prefix-minimum record?

func add(i, d int) {
	for ; i <= n; i += i & -i {
		bit[i] += d
	}
}

func prefix(i int) int {
	r := 0
	for ; i > 0; i -= i & -i {
		r += bit[i]
	}
	return r
}

// kth returns the position of the k-th record (binary lifting on the Fenwick tree).
func kth(k int) int {
	index := 0
	for step := highest; step > 0; step >>= 1 {
		if index+step <= n && bit[index+step] < k {
			k -= bit[index+step]
			index += step
		}
	}
	return index + 1
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n = int(nextInt())
	m := int(nextInt())
	a := make([]int64, n+1)
	active := make([]bool, n+1)
	bit = make([]int, n+1)
	smallest := int64(math.MaxInt64)
	count := 0
	for i := 1; i <= n; i++ {
		a[i] = nextInt()
		if a[i] < smallest {
			smallest = a[i]
			active[i] = true
			count++
		}
	}
	for i := 1; i <= n; i++ {
		if active[i] {
			bit[i]++
		}
		if parent := i + (i & -i); parent <= n {
			bit[parent] += bit[i]
		}
	}
	highest = 1
	for highest*2 <= n {
		highest *= 2
	}
	var out []byte
	for qi := 0; qi < m; qi++ {
		pos := int(nextInt())
		a[pos] -= nextInt()
		rank := prefix(pos)
		changed := true
		if !active[pos] {
			previous := kth(rank) // nearest record to the left
			if a[pos] >= a[previous] {
				changed = false
			} else {
				add(pos, 1)
				active[pos] = true
				count++
				rank++
			}
		}
		// Later records that are no longer strictly smaller than a[pos] stop being records.
		for changed && rank < count {
			following := kth(rank + 1)
			if a[following] < a[pos] {
				break
			}
			add(following, -1)
			active[following] = false
			count--
		}
		if qi > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, int64(count), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
